package com.intellipolis.external;
import com.intellipolis.common.config.ExternalHttp;
import java.net.URI;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import org.springframework.web.util.UriComponentsBuilder;import tools.jackson.databind.JsonNode;
@Service public class ExternalDataService {
 private static final Map<String,String> SIDO=Map.of("부산광역시","210000");
 private static final Map<String,String> SGGU=Map.ofEntries(Map.entry("남구","210001"),Map.entry("동구","210002"),Map.entry("동래구","210003"),Map.entry("부산진구","210004"),Map.entry("북구","210005"),Map.entry("서구","210006"),Map.entry("영도구","210007"),Map.entry("중구","210008"),Map.entry("해운대구","210009"),Map.entry("사하구","210010"),Map.entry("금정구","210011"),Map.entry("강서구","210012"),Map.entry("연제구","210013"),Map.entry("수영구","210014"),Map.entry("사상구","210015"),Map.entry("기장군","210100"));
 private final String publicKey,neisKey;private final RestClient http=ExternalHttp.create();private final Map<String,HospitalData> hospitalCache=new HashMap<>();
 public ExternalDataService(@Value("${app.public-data.api-key:}")String p,@Value("${app.neis.api-key:}")String n){publicKey=p;neisKey=n;}
 public Map<String,Boolean> status(){return Map.of("publicData",!publicKey.isBlank(),"neis",!neisKey.isBlank());}
 public JsonNode hospitals(String sidoCode,String districtCode){require(publicKey,"공공데이터포털");return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B551182/hospInfoServicev2/getHospBasisList").queryParam("serviceKey",publicKey).queryParam("pageNo",1).queryParam("numOfRows",1000).queryParam("sidoCd",sidoCode).queryParam("sgguCd",districtCode).queryParam("_type","json").build().encode().toUri());}
 public synchronized HospitalData hospitalData(String city,String district){require(publicKey,"공공데이터포털");String key=city+"/"+district;if(hospitalCache.containsKey(key))return hospitalCache.get(key);String sido=SIDO.get(city),sggu=SGGU.get(district);if(sido==null||sggu==null)throw new ExternalDataException("지원하지 않는 시·군·구입니다.");JsonNode first=hospitals(sido,sggu,1,100),body=first.path("response").path("body");int count=body.path("totalCount").asInt();List<Location> locations=new ArrayList<>();collectLocations(body,locations);for(int page=2;page<=(count+99)/100;page++)collectLocations(hospitals(sido,sggu,page,100).path("response").path("body"),locations);HospitalData data=new HospitalData(count,List.copyOf(locations));hospitalCache.put(key,data);return data;}
 private void collectLocations(JsonNode body,List<Location> out){JsonNode items=body.path("items").path("item");if(items.isMissingNode()||items.isNull())return;if(items.isArray())items.forEach(x->addLocation(x,out));else addLocation(items,out);}
 private void addLocation(JsonNode item,List<Location> out){double x=number(item,"XPos","xPos"),y=number(item,"YPos","yPos");if(x>=128&&x<=130&&y>=34&&y<=36)out.add(new Location(x,y));}
 private double number(JsonNode node,String a,String b){String value=node.path(a).asText();if(value.isBlank())value=node.path(b).asText();try{return Double.parseDouble(value);}catch(NumberFormatException e){return 0;}}
 private JsonNode hospitals(String sido,String sggu,int page,int rows){return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B551182/hospInfoServicev2/getHospBasisList").queryParam("serviceKey",publicKey).queryParam("pageNo",page).queryParam("numOfRows",rows).queryParam("sidoCd",sido).queryParamIfPresent("sgguCd",Optional.ofNullable(sggu).filter(x->!x.isBlank())).queryParam("_type","json").build().encode().toUri());}
 public JsonNode air(String sido){require(publicKey,"공공데이터포털");return get(UriComponentsBuilder.fromUriString("https://apis.data.go.kr/B552584/ArpltnInforInqireSvc/getCtprvnRltmMesureDnsty").queryParam("serviceKey",publicKey).queryParam("returnType","json").queryParam("numOfRows",100).queryParam("pageNo",1).queryParam("sidoName",sido).queryParam("ver","1.0").build().encode().toUri());}
 public JsonNode schools(String officeCode,String district){require(neisKey,"나이스");return get(UriComponentsBuilder.fromUriString("https://open.neis.go.kr/hub/schoolInfo").queryParam("KEY",neisKey).queryParam("Type","json").queryParam("pIndex",1).queryParam("pSize",1000).queryParam("ATPT_OFCDC_SC_CODE",officeCode).queryParam("LCTN_SC_NM",district).build().encode().toUri());}
 private JsonNode get(URI uri){try{JsonNode body=http.get().uri(uri).retrieve().body(JsonNode.class);if(body==null)throw new ExternalDataException("외부 데이터 응답이 비어 있습니다.");return body;}catch(ExternalDataException e){throw e;}catch(Exception e){throw new ExternalDataException("외부 공공데이터 서버 호출에 실패했습니다.");}}
 private void require(String key,String name){if(key.isBlank())throw new ExternalDataException(name+" API 키가 설정되지 않았습니다.");}
 public record Location(double longitude,double latitude){}
 public record HospitalData(int count,List<Location> locations){}
}
